content.content:
600	        sda = dec_block_sum(sda, red);
601	        sdax = dec_block_sum(sdax, red);
602	        float inv_s = inv[s];
603	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
604	            float dxhat = dyr[j] * gamma[j];
605	            dx_out[s * dec::kD + j] =
606	                inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
607	        }
608	        __syncthreads();
609	    }
610	}
611	
612	// dW += dY^T @ X  for a linear Y = X @ W^T + b. dY [kSeq,out], X [kSeq,in],
613	// dW [out,in]. Owner-thread rule: thread owns (o,i) output element (strided over
614	// out*in), sums over the kSeq positions locally. db[o] += sum_s dY[s,o].
615	// Also returns dX [kSeq,in] += dY @ W into dx_out (caller decides add vs set).
616	//
617	// ldY/ldX/ldDX are the ROW STRIDES (leading dimensions) of dY/X/dx_out. They
618	// are EXPLICIT (no defaults) because the smem scratch buffers this is called on
619	// are 2D arrays whose declared width (e.g. kDff=512 for ff0/gact) differs from
620	// the logical row width (out_dim/in_dim). The original packed-stride version
621	// silently read/wrote the wrong rows at both attention-seam call sites — the
622	// forward stayed exact while every grad upstream of attention was garbage
623	// (params decayed to zero via weight decay; train acc pinned at 1/97). The CPU
624	// structural mirror did NOT catch it (it indexes buffers semantically, not by
625	// flat offset), so the stride is now part of the call contract.
626	__device__ void dec_linear_bwd(
627	        const float* __restrict__ dY, const float* __restrict__ X,
628	        const float* __restrict__ W, int in_dim, int out_dim,
629	        float* __restrict__ dW, float* __restrict__ db,
630	        float* __restrict__ dx_out, bool set_dx,
631	        int ldY, int ldX, int ldDX) {
632	    // dW [out,in] + db [out].
633	    const int wtot = out_dim * in_dim;
634	    for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
635	        const int o = idx / in_dim, i = idx % in_dim;
636	        float acc = 0.0f;
637	        #pragma unroll
638	        for (int s = 0; s < dec::kSeq; ++s)
639	            acc += dY[s * ldY + o] * X[s * ldX + i];
640	        dW[(int64_t)o * in_dim + i] += acc;
641	    }
642	    if (db != nullptr) {
643	        for (int o = threadIdx.x; o < out_dim; o += blockDim.x) {
644	            float acc = 0.0f;
645	            #pragma unroll
646	            for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * ldY + o];
647	            db[o] += acc;
648	        }
649	    }
650	    // dX [kSeq,in] = dY @ W  (W [out,in]).
651	    const int xtot = dec::kSeq * in_dim;
652	    for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
653	        const int s = idx / in_dim, i = idx % in_dim;
654	        float acc = 0.0f;
655	        for (int o = 0; o < out_dim; ++o)
656	            acc += dY[s * ldY + o] * W[(int64_t)o * in_dim + i];
657	        if (set_dx) dx_out[s * ldDX + i] = acc;
658	        else dx_out[s * ldDX + i] += acc;
659	    }
660	    __syncthreads();
661	}
662	
663	// ────────────────────────────────────────────────────────────────────────────
664	//  BACKWARD for one sample (CTA-cooperative). Assumes dec_forward_sample has run
665	//  for THIS sample (so layer_in/final_in/fn caches/logits are populated and
666	//  reflect this sample). Accumulates every weight grad into the CTA's partial
667	//  buffer `g` (DecGrad over gw_cta). Uses extra smem scratch passed via sm.
668	//
669	//  Transcribed from tests/hw/decoder_oracle.py::decoder_backward.
670	// ────────────────────────────────────────────────────────────────────────────
671	__device__ void dec_backward_sample(const DecWeights& w, const DecGrad& g,
672	                                     const int* tokens_s, int target, int B,
673	                                     DecSampleSmem* sm) {
674	    // ── CE backward: dlogits = (softmax - onehot)/B. (logits cached in fwd.) ──
675	    float lmax = -CUDART_INF_F;
676	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
677	        lmax = fmaxf(lmax, sm->logits[o]);
678	    lmax = dec_block_max(lmax, sm->red);
679	    float es = 0.0f;

860	        // both the residual AND the attention-input path; stash dx_in into
861	        // fn_xhat (free again). da stays in ctx.
862	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
863	            const int s = idx / dec::kD, j = idx % dec::kD;
864	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx_in := dr1 (residual)
865	        }
866	        __syncthreads();
867	        // attn out_proj backward: a = ctx_fwd @ out_w^T + out_b. But ctx_fwd
868	        // (the attention context) was overwritten by the recompute's r1/r2 reuse.
869	        // Recompute ctx_fwd from attn + v (cheap): we still have attn[] and qkv[]
870	        // (v lives in qkv[:,2d:3d]). Rebuild ctx_fwd into x1 scratch (x1 no longer
871	        // needed — ff bwd done).
872	        for (int r = threadIdx.x; r < dec::kSeq * dec::kD; r += blockDim.x) {
873	            const int qi = r / dec::kD, col = r % dec::kD;
874	            const int hh = col / dec::kDhead, t = col % dec::kDhead;
875	            float acc = 0.0f;
876	            #pragma unroll
877	            for (int kj = 0; kj <= qi; ++kj)
878	                acc += sm->attn[hh][qi][kj]
879	                     * sm->qkv[kj][2 * dec::kD + hh * dec::kDhead + t];
880	            sm->x1[qi][col] = acc;   // x1 := ctx_fwd
881	        }
882	        __syncthreads();
883	        // da is in ctx. dW_out += da^T @ ctx_fwd(x1); db_out += sum da;
884	        // dctx = da @ out_w -> store into ff0 scratch (free). dctx MUST be
885	        // written at ff0's DECLARED row stride (kDff) — passes A/B below read it
886	        // as sm->ff0[qi][col]; a packed (kD-stride) write only fills row 0's
887	        // first 512 floats and rows 1..3 read stale recomputed pre-GELU values.
888	        dec_linear_bwd(&sm->ctx[0][0], &sm->x1[0][0], L.out_w, dec::kD, dec::kD,
889	                       G.out_w, G.out_b, &sm->ff0[0][0], /*set_dx=*/true, // dctx->ff0
890	                       /*ldY=*/dec::kD, /*ldX=*/dec::kD, /*ldDX=*/dec::kDff);
891	        // ── merge-heads + attention backward (3 synced passes; the forward
892	        //    softmax weights `attn` are read by A and B and NEVER overwritten —
893	        //    dscores go to the dedicated `dsc` buffer). dctx [kSeq,d] is in ff0;
894	        //    v lives in qkv[:,2d:3d], k in qkv[:,d:2d], q in qkv[:,0:d]. dqkv is
895	        //    built into gact[:, :3d]. Transcribed from the oracle's attention bwd:
896	        //      dvh   = attn^T @ dctxh
897	        //      dattn = dctxh @ vh^T ; dscores = softmax_bwd(dattn,attn) * scale
898	        //      dqh   = dscores @ kh ; dkh = dscores^T @ qh                       ─
899	        const float scale = dec::attn_scale();
900	        // A: dv into gact[:, 2d:3d].  dv[kj,qoff+t] = Σ_{qi>=kj} attn[hh][qi][kj]
901	        //    * dctx[qi, qoff+t].  (Owner: thread per (kj, head, t).)
902	        for (int r = threadIdx.x; r < dec::kSeq * dec::kHeads * dec::kDhead;
903	             r += blockDim.x) {
904	            const int kj = r / (dec::kHeads * dec::kDhead);
905	            const int rem = r % (dec::kHeads * dec::kDhead);
906	            const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
907	            const int qoff = hh * dec::kDhead;
908	            float acc = 0.0f;
909	            #pragma unroll
910	            for (int qi = kj; qi < dec::kSeq; ++qi)   // qi>=kj (causal: kj<=qi)
911	                acc += sm->attn[hh][qi][kj] * sm->ff0[qi][qoff + t];
912	            sm->gact[kj][2 * dec::kD + qoff + t] = acc;   // dv block
913	        }
914	        __syncthreads();
915	        // B: dscores into dsc.  datt[hh,qi,kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t];
916	        //    ds = attn*(datt - Σ_k datt*attn)*scale  (masked kj>qi → 0).
917	        for (int r = threadIdx.x; r < dec::kHeads * dec::kSeq; r += blockDim.x) {
918	            const int hh = r / dec::kSeq, qi = r % dec::kSeq;
919	            const int qoff = hh * dec::kDhead;
920	            float datt[dec::kSeq];
921	            #pragma unroll
922	            for (int kj = 0; kj < dec::kSeq; ++kj) {
923	                if (kj > qi) { datt[kj] = 0.0f; continue; }
924	                float acc = 0.0f;
925	                #pragma unroll
926	                for (int t = 0; t < dec::kDhead; ++t)
927	                    acc += sm->ff0[qi][qoff + t]
928	                         * sm->qkv[kj][2 * dec::kD + qoff + t];
929	                datt[kj] = acc;
930	            }
931	            float dot = 0.0f;
932	            #pragma unroll
933	            for (int kj = 0; kj <= qi; ++kj) dot += datt[kj] * sm->attn[hh][qi][kj];
934	            #pragma unroll
935	            for (int kj = 0; kj < dec::kSeq; ++kj) {
936	                float a = sm->attn[hh][qi][kj];
937	                sm->dsc[hh][qi][kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale
938	                                                 : 0.0f;
939	            }
940	        }
941	        __syncthreads();
942	        // C: dq into gact[:,0:d], dk into gact[:,d:2d].
943	        //    dq[qi,qoff+t] = Σ_kj dsc[hh][qi][kj]*k[kj,qoff+t];
944	        //    dk[kj,qoff+t] = Σ_qi dsc[hh][qi][kj]*q[qi,qoff+t].  (Owner: pos,head,t.)
945	        for (int r = threadIdx.x; r < dec::kSeq * dec::kHeads * dec::kDhead;
946	             r += blockDim.x) {
947	            const int pos = r / (dec::kHeads * dec::kDhead);
948	            const int rem = r % (dec::kHeads * dec::kDhead);
949	            const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
950	            const int qoff = hh * dec::kDhead;
951	            float dq = 0.0f, dk = 0.0f;
952	            #pragma unroll
953	            for (int kj = 0; kj < dec::kSeq; ++kj) {
954	                dq += sm->dsc[hh][pos][kj] * sm->qkv[kj][dec::kD + qoff + t];
955	                dk += sm->dsc[hh][kj][pos] * sm->qkv[kj][qoff + t];
956	            }
957	            sm->gact[pos][qoff + t] = dq;            // dq block (gact[:,0:d])
958	            sm->gact[pos][dec::kD + qoff + t] = dk;  // dk block (gact[:,d:2d])
959	        }
960	        __syncthreads();
961	        // in_proj backward: dqkv (gact[:, :3d]) -> dW in, db in, dx_in += dqkv @ in_w.
962	        // x_in = layer_in[li]. dqkv was written 2D (sm->gact[pos][col]) so dY's
963	        // row stride is gact's DECLARED width kDff — a packed (3d=384) read
964	        // walks off row 0 into the stale dff0 values left in gact[0][384:512].
965	        dec_linear_bwd(&sm->gact[0][0], &sm->layer_in[li][0][0], L.in_w,
966	                       dec::kD, 3 * dec::kD, G.in_w, G.in_b,
967	                       &sm->fn_xhat[0][0], /*set_dx=*/false,   // dx_in += attn path
968	                       /*ldY=*/dec::kDff, /*ldX=*/dec::kD, /*ldDX=*/dec::kD);
969	        // dh for the previous layer = dx_in (in fn_xhat). Move to dh.

