74	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
75	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
76	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
77	//
78	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
79	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
80	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
81	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
82	// total == kDecTotalElems == 422755.
83	
84	struct DecoderTokenCtx {
85	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
86	    const int* targets;  // [B]       int32 target ids
87	    int        B;        // batch size (full-batch in the race ≈ 4191)
88	    float*     workspace; // grad partials + loss partials + reduced loss
89	    float*     loss_out;  // device float the kernel writes the mean loss into
90	};
91	
92	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
93	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
94	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
95	//    the launcher is unchanged). ────────────────────────────────────────────────
96	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
97	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
98	// the reduce + optimizer phases read them directly. This also lets the host side
99	// (dispatch.cpp) avoid building any layout tensors.
100	template <OptId Opt>
101	__global__ void __launch_bounds__(256)
102	fused_decoder_megakernel(PersistentContext ctx,
103	                         float* __restrict__ params,
104	                         DecoderTokenCtx tok,
105	                         float* __restrict__ grad,        // reduced grad [total]
106	                         float lr, int step, FusedOptState st) {
107	    __shared__ DecSampleSmem sm;
108	    GridBarrier bar = ctx.barrier();
109	    const int cta = blockIdx.x;
110	    const int nCTA = (int)ctx.n_ctas;
111	    const int64_t total = kDecTotalElems;
112	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
