68	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor slice
69	// at `off` within the flat [m|v|extra] layout. Per-TENSOR fields and all scalars
70	// pass through unchanged. (Identical to the decoder's rebase_state; redefined here
71	// under a vit_ name so this header stays self-contained — the decoder file is
72	// owned by a sibling agent and must not be included.)
73	template <OptId Opt>
74	__device__ __forceinline__ FusedOptState
75	vit_rebase_state(const FusedOptState& s, int64_t off) {
76	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
77	    if (t.exp_avg)    t.exp_avg    += off;
78	    if (t.exp_avg_sq) t.exp_avg_sq += off;
79	    if (t.ema)        t.ema        += off;
80	    if (t.sam_dir)    t.sam_dir    += off;
81	    if (t.s_track)    t.s_track    += off;
82	    if (t.mu)         t.mu         += off;
83	    if (t.orth)       t.orth       += off;
84	    if (t.smart_grad) t.smart_grad += off;
85	    return t;
86	}
