88	// The L3-REAL ViT megakernel needs the FLOAT patch path + a grad-partial
89	// workspace. Kept a SEPARATE kernel + launcher (not folded into the surrogate
90	// fused_megakernel) so the surrogate path is untouched.
91	//
92	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
93	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
94	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
95	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
96	// total == kVitTotalElems == 418017.
97	struct ViTInputCtx {
98	    const float* patches;  // [B, kNPatch, kPatch] fp32 image patches
99	    const int*   targets;  // [B]                  int32 target ids in [0,kVocab)
100	    int          B;        // batch size
101	    float*       workspace; // grad partials + loss partials + reduced loss
102	    float*       loss_out;  // device float the kernel writes the mean loss into
103	};
104	
105	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
106	//    threads/CTA. VitSampleSmem (~183.67 KB) lives in DYNAMIC smem (extern). ────
107	// sizes/offsets are NOT host-passed: per-tensor numel/offset live in the
108	// __constant__ tables kVitSizes/kVitOffsets (vit_layout.cuh), read directly by
109	// the reduce + optimizer phases.
110	template <OptId Opt>
111	__global__ void __launch_bounds__(256)
112	fused_vit_megakernel(PersistentContext ctx,
113	                     float* __restrict__ params,
114	                     ViTInputCtx in,
115	                     float* __restrict__ grad,        // reduced grad [total]
116	                     float lr, int step, FusedOptState st) {
117	    extern __shared__ char vit_smem_raw[];
118	    VitSampleSmem& sm = *reinterpret_cast<VitSampleSmem*>(vit_smem_raw);
119	    GridBarrier bar = ctx.barrier();
120	    const int cta = blockIdx.x;
121	    const int nCTA = (int)ctx.n_ctas;
122	    const int64_t total = kVitTotalElems;
123	    float* my_partial = in.workspace + (int64_t)cta * total;   // this CTA's dW
124	    float* loss_part = in.workspace + (int64_t)nCTA * total;   // [nCTA]
125	
126	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
127	    const int wg = threadIdx.x / 128;
128	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
129	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
130	
131	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
132	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
133	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
134	    bar.sync();   // B0
135	
136	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
137	    VitWeights w = vit_bind(params);
138	    VitGrad g = vit_bind_grad(my_partial);
139	    const int B = in.B;
140	    const int base = B / nCTA, rem = B % nCTA;
141	    const int b0 = cta * base + (cta < rem ? cta : rem);
142	    const int cnt = base + (cta < rem ? 1 : 0);
143	    const int b1 = b0 + cnt;
144	    __shared__ int tgt_s;
145	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
146	    const int patch_elems = vit::kNPatch * vit::kPatch;   // 16*49 = 784
147	    for (int b = b0; b < b1; ++b) {
148	        // Load this sample's float patches into smem (cooperative).
149	        const float* src = in.patches + (int64_t)b * patch_elems;
150	        for (int i = threadIdx.x; i < patch_elems; i += blockDim.x)
151	            sm.patch[i / vit::kPatch][i % vit::kPatch] = src[i];
152	        if (threadIdx.x == 0) tgt_s = in.targets[b];
153	        __syncthreads();
154	        float nll = vit_forward_sample(w, tgt_s, &sm);
155	        vit_backward_sample(w, g, tgt_s, B, &sm);
156	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
157	        __syncthreads();   // sample boundary: all grad writes done before reuse
158	    }
159	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
160	    bar.sync();   // B1: all CTA partials + loss slots complete
161	
162	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
163	    //    (one task = one parameter tensor; sum its elements across CTAs in
164	    //    ascending CTA index). Summation ORDER (ascending cta) is fixed →
165	    //    deterministic regardless of which CTA grabs the task. ─────────────────
166	    {
167	        __shared__ int task_slot;
168	        TaskQueue q = ctx.queue();
169	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
170	             t = q.next_block(&task_slot)) {
171	            const int n = kVitSizes[t];
172	            const int64_t off = (int64_t)kVitOffsets[t];
173	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
174	                float acc = 0.0f;
175	                for (int c = 0; c < nCTA; ++c)
176	                    acc += in.workspace[(int64_t)c * total + off + i];
177	                grad[off + i] = acc;
178	            }
179	        }
180	    }
181	    // Loss reduction (fp64 ordered) by CTA 0 only — the loss rel-tol is the
182	    // tightest gate; fp32 atomic-summing many terms can miss it.
183	    if (cta == 0 && threadIdx.x == 0) {
184	        double s = 0.0;
185	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
186	        float mean = (float)(s / (double)B);
187	        *in.loss_out = mean;
188	    }
189	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
190	
191	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 32
192	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
193	    st.lr = lr;
194	    {
195	        __shared__ int task_slot;
196	        TaskQueue q = ctx.queue();
197	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
198	             t = q.next_block(&task_slot)) {
199	            const int n = kVitSizes[t];
200	            const int64_t off = (int64_t)kVitOffsets[t];
201	            const FusedOptState ts = vit_rebase_state<Opt>(st, off);
202	            float* __restrict__ p = params + off;
203	            const float* __restrict__ gg = grad + off;
204	            for (int i = threadIdx.x; i < n; i += blockDim.x)
205	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
206	        }
207	    }
208	}
