958	        // compute dW_dt + db_dt (reads ddt_pre=a->dt_pre, dt_raw=dbc[:,:8]), then
959	        // ddt_raw (reads ddt_pre + dt_proj_w) overwriting dbc[:,:8].
960	        {
961	            const float* dY = &a->dt_pre[0][0];   // ddt_pre [kSeq,d_inner]
962	            // dW_dt [d_inner, dt_rank]; db_dt [d_inner].
963	            const int wtot = mb::kDInner * mb::kDtRank;
964	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
965	                const int o = idx / mb::kDtRank, i = idx % mb::kDtRank;
966	                float acc = 0.0f;
967	                #pragma unroll
968	                for (int s = 0; s < mb::kSeq; ++s) acc += dY[s * mb::kDInner + o] * sm->dbc[s][i];
969	                G.dt_proj_w[(int64_t)o * mb::kDtRank + i] += acc;
970	            }
971	            for (int o = threadIdx.x; o < mb::kDInner; o += blockDim.x) {
972	                float acc = 0.0f;
973	                #pragma unroll
974	                for (int s = 0; s < mb::kSeq; ++s) acc += dY[s * mb::kDInner + o];
975	                G.dt_proj_b[o] += acc;
976	            }
977	            __syncthreads();
978	            // ddt_raw[s,i] = Σ_o ddt_pre[s,o]*dt_proj_w[o,i] -> dbc[:, :dt_rank].
979	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDtRank; idx += blockDim.x) {
980	                const int s = idx / mb::kDtRank, i = idx % mb::kDtRank;
981	                float acc = 0.0f;
982	                for (int o = 0; o < mb::kDInner; ++o) acc += dY[s * mb::kDInner + o] * L.dt_proj_w[(int64_t)o * mb::kDtRank + i];
983	                sm->dbc[s][i] = acc;   // ddt_raw -> dbc[:, :dt_rank]
984	            }
985	            __syncthreads();
986	        }
987	        // (9) assemble dx_dbc = cat[ddt_raw, dBmat, dCmat] into dbc (ddt_raw already
988	        //   in dbc[:, :dt_rank]; place dB,dC after).
989	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kState; idx += blockDim.x) {
990	            const int s = idx / mb::kState, k = idx % mb::kState;
991	            sm->dbc[s][mb::kDtRank + k] = sm->dBmat[s][k];
992	            sm->dbc[s][mb::kDtRank + mb::kState + k] = sm->dCmat[s][k];
993	        }
994	        __syncthreads();
995	        //   x_proj bwd: dW_xproj += dx_dbc^T @ x_main ; dx_main(x_proj path) =
996	        //   dx_dbc @ x_proj_w  -> ADD into the dx_main accumulator (adj_a). x_main
997	        //   = adj_c (still valid).
998	        {
999	            const float* dY = &sm->dbc[0][0];     // dx_dbc [kSeq,40]
1000	            const float* X = &sm->adj_c[0][0];    // x_main [kSeq,d_inner]
1001	            const int wtot = mb::kDbc * mb::kDInner;
1002	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
1003	                const int o = idx / mb::kDInner, i = idx % mb::kDInner;
1004	                float acc = 0.0f;
1005	                #pragma unroll
1006	                for (int s = 0; s < mb::kSeq; ++s) acc += dY[s * mb::kDbc + o] * X[s * mb::kDInner + i];
1007	                G.x_proj_w[(int64_t)o * mb::kDInner + i] += acc;
1008	            }
1009	            __syncthreads();
1010	            // dx_main += dx_dbc @ x_proj_w (ADD into adj_a).
1011	            const int xtot = mb::kSeq * mb::kDInner;
1012	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
1013	                const int s = idx / mb::kDInner, i = idx % mb::kDInner;
1014	                float acc = 0.0f;
1015	                for (int o = 0; o < mb::kDbc; ++o) acc += dY[s * mb::kDbc + o] * L.x_proj_w[(int64_t)o * mb::kDInner + i];
1016	                sm->adj_a[s][i] += acc;   // dx_main += x_proj path
1017	            }
1018	            __syncthreads();
1019	        }
1020	        // (10-11) dx_main complete (adj_a). dconv = dx_main * silu'(conv) -> adj_c
1021	        //   (x_main no longer needed). conv1d bwd: dx_main_raw + dW_conv + db_conv.
1022	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
1023	            const int s = idx / mb::kDInner, c = idx % mb::kDInner;
1024	            sm->adj_c[s][c] = sm->adj_a[s][c] * mb_silu_grad(a->conv[s][c]);   // dconv
1025	        }
1026	        __syncthreads();
1027	        //   conv bwd: dx -> adj_a (dx_main_raw); reads dconv=adj_c, in=x_main_raw.
1028	        mb_conv1d_bwd(&sm->adj_c[0][0], &a->x_main_raw[0][0], L.conv_w,
1029	                      G.conv_w, G.conv_b, &sm->adj_a[0][0]);   // adj_a := dx_main_raw
1030	        // (12) dxz = cat[dx_main_raw, dz] (adj_a | adj_b). in_proj bwd: dW_in +=
1031	        //   dxz^T @ hin ; dx_inproj = dxz @ in_w.  in_w is [2*d_inner, d]; rows
1032	        //   [0,d_inner) pair with x_main_raw, [d_inner,2di) with z.
1033	        //   dx (=dx_inproj + dx_residual) goes to the previous layer's dh.
1034	        {
1035	            // dW_in: rows 0..d_inner-1 from dx_main_raw(adj_a), d_inner..2di-1 from dz(adj_b).
1036	            const int half = mb::kDInner;
1037	            for (int o = threadIdx.x; o < 2 * mb::kDInner; o += blockDim.x) {
1038	                const float* dyo = (o < half) ? &sm->adj_a[0][0] : &sm->adj_b[0][0];
1039	                const int oo = (o < half) ? o : (o - half);
1040	                for (int i = 0; i < mb::kD; ++i) {
1041	                    float acc = 0.0f;
1042	                    #pragma unroll
1043	                    for (int s = 0; s < mb::kSeq; ++s)
1044	                        acc += dyo[s * mb::kDInner + oo] * hin[s * mb::kD + i];
1045	                    G.in_w[(int64_t)o * mb::kD + i] += acc;
1046	                }
1047	            }
1048	            __syncthreads();
1049	            // dx_inproj[s,i] = Σ_{o<d_inner} dx_main_raw[s,o]*in_w[o,i]
1050	            //               + Σ_{o<d_inner} dz[s,o]*in_w[d_inner+o,i]
1051	            //   then + dx_residual (sm->dr). Write into dh for the previous layer.
1052	            for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1053	                const int s = idx / mb::kD, i = idx % mb::kD;
1054	                float acc = 0.0f;
