1059	                sm->dh[s][i] = acc + sm->dr[s][i];   // (13) dx = in_proj path + residual
1060	            }
1061	            __syncthreads();
1062	        }
1063	        // dh now = grad wrt the previous layer's output (or the embedding for li=0).
1064	    }
1065	
1066	    // ── embedding backward: dh = grad wrt h0 [kSeq,d]. ──
1067	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1068	        #pragma unroll
1069	        for (int s = 0; s < mb::kSeq; ++s) {
1070	            float d = sm->dh[s][j];
1071	            g.tok[(int64_t)tokens_s[s] * mb::kD + j] += d;
1072	            g.pos[(int64_t)s * mb::kD + j] += d;
1073	        }
1074	    }
1075	    __syncthreads();
1076	}
