955	// S5 apply: unsort expert_out then sg2_apply_step per ORIGINAL element. The
956	// expert output is in SORTED order; element i's value is expert_out_sorted[
957	// unsort[i]]. sg2_apply_step is the canonical csrc/algorithms math (CALLED).
958	template <typename Dims, typename ParamT, typename GradT>
959	__device__ __forceinline__ void sg2_stage_apply(
960	    ParamT* __restrict__ param,        // [N] tensor slice
961	    float* __restrict__ exp_avg, float* __restrict__ exp_avg_sq,
962	    float* __restrict__ mu_state, float* __restrict__ slow_state,
963	    const GradT* __restrict__ grad,    // [N] original order
964	    const float* __restrict__ expert_out_sorted,  // [N] sorted
965	    const int* __restrict__ unsort,    // [N] original-row -> sorted-row
966	    float alpha, float gru_decay, float lamb_eff,
967	    float lr, float beta1, float beta2, float eps, float wd,
968	    float bc1, float bc2, int N) {
969	    for (int i = threadIdx.x; i < N; i += blockDim.x) {
970	        const float eo = expert_out_sorted[unsort[i]];
971	        sg2alg::sg2_apply_step(
972	            param, exp_avg, exp_avg_sq, mu_state, slow_state, grad,
973	            eo, alpha, gru_decay, lamb_eff,
974	            lr, beta1, beta2, eps, wd, bc1, bc2, (int64_t)i);
975	    }
976	}
