1110	// =====================================================================
1111	//  The persistent megakernel: ONE launch runs the SG2 optimizer step for
1112	//  ALL parameter tensors. gridDim.x = #SMs, 256 thr/CTA. Each CTA pulls
1113	//  WHOLE tensors from the task queue and runs sg2_meta_stages for each.
1114	//  ONE grid barrier at the end (so a composing model stage can reset the
1115	//  queue). The weight bundle is staged into smem ONCE per CTA up front.
1116	// =====================================================================
1117	#ifndef SG2_MEGA_BLOCK
1118	#define SG2_MEGA_BLOCK 256
1119	#endif
1120	
1121	template <typename Dims, typename ParamT, typename GradT>
1122	__global__ void __launch_bounds__(SG2_MEGA_BLOCK)
1123	sg2_meta_optimizer_megakernel(
1124	    PersistentContext ctx,
1125	    SG2Weights w,
1126	    SG2State st,
1127	    SG2Scalars sc,
1128	    ParamT* __restrict__ params,
1129	    const GradT* __restrict__ grads,
1130	    const float* __restrict__ sharpness) {
1131	    // Stage the (small) weight bundle into shared memory once per CTA.
1132	    __shared__ SG2SmemWeights<Dims> sw;
1133	    sg2_stage_weights<Dims>(sw, w);
1134	    __syncthreads();
1135	
1136	    GridBarrier bar = ctx.barrier();
1137	    float* my_ws = st.workspace + (int64_t)blockIdx.x * st.ws_stride;
1138	
1139	    // Work-steal WHOLE tensors. Each tensor's full pipeline is CTA-local.
1140	    __shared__ int task_slot;
1141	    TaskQueue q = ctx.queue();
1142	    for (int t = q.next_block(&task_slot); t < st.n_tensors;
1143	         t = q.next_block(&task_slot)) {
1144	        sg2_meta_stages<Dims, ParamT, GradT>(
1145	            sw, t, st, sc, params, grads, sharpness, my_ws);
1146	    }
1147	
1148	    // ONE grid barrier: lets a composing model stage reset the queue after the
1149	    // optimizer tail drains. (Standalone, this is just a clean exit fence.)
1150	    bar.sync();
1151	}
1152	
1153	// =====================================================================
1154	//  Host launcher — one persistent CTA per SM, SG2_MEGA_BLOCK thr/CTA.
1155	//  Mirrors launch_fused_decoder_megakernel's hang-freedom contract:
1156	//  occupancy>=1 or refuse (the GridBarrier rendezvous of n_ctas CTAs can
1157	//  never complete if a CTA cannot be placed). Zeroes the barrier+queue
1158	//  counters per launch. The caller allocates the workspace + index buffers
1159	//  and PRE-COMPUTES perm/unsort (the one explicit pre-kernel sort step).
1160	// =====================================================================
1161	template <typename Dims, typename ParamT, typename GradT>
1162	cudaError_t launch_sg2_meta_optimizer_tail(
1163	    PersistentContext ctx,
1164	    SG2Weights w, SG2State st, SG2Scalars sc,
1165	    ParamT* params, const GradT* grads, const float* sharpness,
1166	    cudaStream_t stream) {
1167	    int dev = 0;
1168	    cudaError_t err = cudaGetDevice(&dev);
1169	    if (err != cudaSuccess) return err;
1170	    int n_sms = 0;
1171	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1172	    if (err != cudaSuccess) return err;
1173	
1174	    int occ = 0;
1175	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1176	        &occ, (const void*)&sg2_meta_optimizer_megakernel<Dims, ParamT, GradT>,
1177	        SG2_MEGA_BLOCK, /*dynamicSMemBytes=*/0);
1178	    if (err != cudaSuccess) return err;
1179	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1180	
1181	    const unsigned launch_ctas = (unsigned)n_sms;
1182	    ctx.n_ctas = launch_ctas;
1183	    ctx.n_tasks = st.n_tensors;
1184	
1185	    if (ctx.g_arrived)   { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1186	    if (ctx.g_generation){ err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1187	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1188	
1189	    dim3 grid(launch_ctas), block(SG2_MEGA_BLOCK);
1190	    sg2_meta_optimizer_megakernel<Dims, ParamT, GradT><<<grid, block, 0, stream>>>(
1191	        ctx, w, st, sc, params, grads, sharpness);
1192	    return cudaGetLastError();
1193	}
